WITH filtered AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, CASE WHEN amount >= 3600 THEN 'High' WHEN amount >= 800 THEN 'Medium' ELSE 'Low' END AS amount_level, COALESCE(merchant, 'N/A') AS merchant_filled FROM transactions WHERE txn_time >= DATE '2023-06-05'), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_session FROM filtered), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN session_no >= 8 THEN 'LARGE' ELSE 'SMALL' END AS session_no_tier, SIZE(COLLECT_SET(merchant)) AS num_merchants, SUM(session_no) FILTER (WHERE merchant = 'Amazon') AS amazon_total_session_no, MAX(txn_time) AS ended_at FROM sessions_transactions GROUP BY CASE WHEN session_no >= 8 THEN 'LARGE' ELSE 'SMALL' END HAVING amazon_total_session_no > 0 ORDER BY amazon_total_session_no DESC NULLS LAST
